{
 "@context": "https://schema.org",
 "@type": "FAQPage",
 "mainEntity": [{
  "@type": "Question",
  "name": "How much data can 10GB hold?",
  "acceptedAnswer": {
   "@type": "Answer",
   "text": "The average user stores a mix of digital media (photos and videos) and documents. 10GB gives you the option of storing roughly: 2,000 songs or pictures More than 50,000 documents"
  }
 },{
  "@type": "Question",
  "name": "Can I share my files and folders with someone who doesn’t have a Box account?",
  "acceptedAnswer": {
   "@type": "Answer",
   "text": "Yes! You can create an external link that can be shared with anyone, even people without a Box account. (Though while you’re at it, why not encourage them to start a free Box account?! That way you can collaborate with them and co-edit the document.)"
  }
 },{
  "@type": "Question",
  "name": "Can I buy more storage space on my plan?",
  "acceptedAnswer": {
   "@type": "Answer",
   "text": "If you have an Individual plan, you can free up space by deleting unused files and folders, or you can choose an upgraded plan (with unlimited storage available) that meets your needs."
  }
 },{
  "@type": "Question",
  "name": "Can I access my Box account via mobile?",
  "acceptedAnswer": {
   "@type": "Answer",
   "text": "Absolutely! Download the Box Mobile App to access your content anywhere, anytime."
  }
 }]
}

